\begin{appendix}
In this Appendix, we provide technical details that support the statements from the main text.

\section{Proof of~\cref{th}}\label{app:theorem1}
We start by writing each mutual information term from the generalized IC statement in \cref{eq:ic_correlated} separately.
\begin{align}
I(x_0;m',b\vert y=0)&=H(m',b\vert y=0)-\sum_{j\in\{0,1\}}\Pr(x_0=j)H(m',b\vert x_0=j, y=0).~\label{eq:ICLHS0}\\
I(x_1;m',b\vert y=1, x_0)&=\sum_{j\in\{0,1\}}\Pr(x_0=j)H(m',b\vert x_0=j, y=1)\nonumber\\&
    -\sum_{j,k\in\{0,1\}}\Pr(x_0=j, x_1=k)H(m',b\vert x_0=j, x_1=k, y=1).~\label{eq:ICLHS1}\\
I(m;m')&=H(m')-\sum_{l\in\{0,1\}^3} \Pr(m=l)H(m'\vert m=l).~\label{eq:ICRHS}
\end{align}
The probabilities of the shared non-signaling resource can be expressed in terms of the correlators as
\begin{equation}\label{eq:pabxy}
    \Pr(a,b\vert x,y) = \frac{1}{4}\left(1+(-1)^a\mean{a_x}+(-1)^b\mean{b_y}+(-1)^{a\oplus b}\mean{a_xb_y}\right),
\end{equation}
for $a,b,x,y\in\Set{0,1}$.
The marginal probabilities are then equal to
\begin{equation}\label{eq:paxpby}
    \Pr(a\vert x) = \frac{1}{2}(1+(-1)^a\mean{a_x}),\quad \Pr(b\vert y) = \frac{1}{2}(1+(-1)^b\mean{b_y}).
\end{equation}
In this work, we consider the communication channel taking the entire data on Alice's side, namely $m=(x_0,x_1,a)$, as its input and producing the output $m'\in\Set{0,1}$.
The channel of this form can be parametrized in the following way
\begin{equation}\label{eq:channel_probs}
    \Pr(m'\vert m) = \frac{1}{2}+(-1)^{m'}\frac{e_c}{2}f_m,
\end{equation}
for $m'\in\Set{0,1}$, $m\in\Set{0,1}^3$, and $e_c,f_m\in \RR$.
As long as $\abs{e_cf_m}\leq 1$, the probabilities in \cref{eq:channel_probs} are non-negative and sum up to $1$ for each $m$, i.e., the corresponding channel exists.
The parameter $e_c$ in \cref{eq:channel_probs} plays the role of determining the strength of the noise in the channel.

Next, we write down each probability necessary for calculating the entropy functions in \cref{eq:ICLHS0,eq:ICLHS1,eq:ICRHS}.
\begin{align}\label{eq:probs_gen}
\Pr(m',b\vert x_0,x_1,y) = \sum_a \Pr(m'\vert x_0,x_1,a)\Pr(a,b\vert \xor,y) = \frac{\Pr(b|y)}{2}
+\frac{(-1)^{m'}e_c}{2}
\underbrace{
\sum_a f_{x_0,x_1,a}\Pr(a,b|\xor,y)
}_{\eqqcolon\,\chi_{x_0,x_1,y}^{b}},
\end{align}
where $\chi_{x_0,x_1,y}^{b}\in \RR$, and we substituted the conditioning on $x_0,x_1$ with $\xor$ in the probability above, because we fix Alice's measurement choice to be $\xor$. 
From \cref{eq:probs_gen}, we can calculate the rest of the probabilities
\begin{align}\begin{split}
\Pr(m',b|y=0)
&= \frac{\Pr(b|y=0)}{2}
+\frac{(-1)^{m'}e_c}{2}
\sum_{x_0,x_1} \left(\sum_{a} f_{x_0,x_1,a}\Pr(a,b|\xor,y=0)\right)\Pr(x_0,x_1)\\
&= \frac{\Pr(b|y=0)}{2}
+\frac{(-1)^{m'}e_c}{2}
\sum_{x_0,x_1} \Pr(x_0,x_1) \chi_{x_0,x_1,0}^b,
\end{split}\end{align}
and
\begin{align}\begin{split}
\Pr(m',b|x_0,y)
&= \frac{\Pr(b|y)}{2}
+\frac{(-1)^{m'}e_c}{2}
\sum_{x_1} \left(\sum_{a} f_{x_0,x_1,a}\Pr(a,b|\xor,y=0)\right)\Pr(x_1\vert x_0)\\
&= \frac{\Pr(b|y)}{2}
+\frac{(-1)^{m'}e_c}{2}
\sum_{x_1} \Pr(x_1|x_0) \chi_{x_0,x_1,0}^b.
\end{split}\end{align}
We now use the technique, which we introduced in Ref.~\cite{jain2024informationcausality}, to obtain quadratic constraints from the IC statement.
In short, we consider the limit of the IC inequality for the channel capacity going to $0$, which corresponds to $e_c\to 0$. This limit can be obtained using l'H{\^o}pital's rule and effectively replaces each summand in the IC statement with the limit of its second derivative for $e_c\to 0$.
We use the following general formula
\begin{equation}
    \lim_{e_c\to 0}\frac{\partial^2}{\partial e_c^2}(\xi+e_c\eta)\log(\xi+e_c\eta) = \frac{\eta^2}{\xi},
\end{equation}
for $\xi,\eta\in \RR$ to avoid identical calculations for each of the entropy terms. 
This results in the following implication of the IC statement in \cref{eq:ic_correlated},
\begin{align}\label{eq:afterlimchi}
\begin{split}
-&\sum_{b} \frac{\left(\sum_{x_0,x_1} \chi_{x_0,x_1, 0}^b \Pr(x_0,x_1)\right)^2}{\Pr(b|y=0)} + \frac{1}{2}\sum_{x_0,b,y} (-1)^y\frac{\left(\sum_{x_1} \chi_{x_0,x_1,y}^b \Pr(x_1|x_0)\right)^2}{\Pr(b|y)}+\sum_{x_0,x_1} \Pr(x_0,x_1)\sum_b \frac{(\chi_{x_0,x_1,1}^b)^2}{\Pr(b\vert y=1)}\\
\leq&-\left(\sum_{x_0,x_a,a} f_{x_0,x_1,a}\Pr(a\vert \xor) \Pr(x_0,x_1) \right)^2+\sum_{x_0,x_a,a} \Pr(a\vert \xor) \Pr(x_0,x_1)f_{x_0,x_1,a}^2.
\end{split}
\end{align}
We now fix the form of the parameters $f_{x_0,x_1,a}$ to be
\begin{equation}\label{eq:fx0x1a}
 f_{x_0,x_1,a} = (-1)^{a\oplus x_0}\frac{\kappa_{\xor}}{\sax{\xor}},
\end{equation}
for $\kappa_0,\kappa_1\in\RR$. Inserting this expression and the parametrization of probabilities in~\cref{eq:pabxy} in the definition of $\chi_{x_0,x_1,y}^b$, we obtain,
\begin{equation}
    \chi_{x_0,x_1,y}^b = \frac{(-1)^{x_0}}{2}\frac{\kappa_{\xor}}{\sax{\xor}}\left(\mean{a_{\xor}}+(-1)^b\mean{a_{\xor}b_y}\right).
\end{equation}
We incorporate this parametrization in the individual summand in~\cref{eq:afterlimchi}.
For the first summand, we show that the numerator is zero. Indeed,
\begin{align}
    \begin{split}
        \sum_{x_0,x_1} \chi_{x_0,x_1, 0}^b \Pr(x_0,x_1)= \sum_{x_0,x_1} \frac{(-1)^{x_0}}{2}\frac{\kappa_{\xor}}{\sax{\xor}}\left(\mean{a_{\xor}}+(-1)^b\mean{a_{\xor}b_0}\right) \frac{1+(-1)^{\xor}\veps}{4}=0.
    \end{split}
\end{align}
Apart from the factor $(-1)^{x_0}$, the rest of the expression depends on $x_0$ and $x_1$ only through their parity $\xor$. For each fixed value of this parity, the two corresponding pairs $(x_0,x_1)$ therefore contribute with equal magnitude and opposite signs, and hence cancel exactly.

Moving to the second summand, since the two terms only differ in Bob's setting $y$, we keep the input unspecified,
\begin{align}\label{eq:second_sum_pre}
    \begin{split}
        \sum_{x_0,b} \frac{\left(\sum_{x_1} \chi_{x_0,x_1, 0}^b \Pr(x_1|x_0)\right)^2}{\Pr(b|y)}=&\sum_{x_0,b} \frac{\left(\sum_{x_1} \frac{\kappa_{\xor}}{\sax\xor}\left(\mean{a_{\xor}}+(-1)^b\mean{a_{\xor}b_y}\right) \frac{1+(-1)^{\xor}\veps}{2}\right)^2}{2 (1+(-1)^b\mean{b_y}) }\\
        =&\sum_{b} \frac{\left(\sum_{x} \frac{\kappa_{x}}{\sax{x}}\left(\mean{a_{x}}+(-1)^b\mean{a_{x}b_y}\right) \frac{1+(-1)^{x}\veps}{2}\right)^2}{1+(-1)^b\mean{b_y} }.
    \end{split}
\end{align}
We can rewrite the terms in the numerator in the re-normalized correlator notation in \cref{eq:Dxy},
\begin{equation}
\mean{a_x}+(-1)^b\mean{a_xb_y} = \left(1+(-1)^b\mean{b_y}\right)\mean{a_x} + (-1)^b\sax{x}\sqrt{1-\mean{b_y}^2} D_{x,y}.
\end{equation}
This leads to a simplified form of the expression in \cref{eq:second_sum_pre},
\begin{align}
&\sum_b\frac{1}{1+(-1)^b\mean{b_y}}\left[\left(1+(-1)^b\mean{b_y}\right)\sum_x\frac{\kappa_x\mean{a_x}}{\sax{x}}\frac{1+(-1)^x\veps}{2} + (-1)^b\sqrt{1-\mean{b_y}^2}\sum_x\kappa_x D_{x,y}\frac{1+(-1)^x\veps}{2}\right]^2
\nonumber\\
&=2\left[\sum_x\frac{\kappa_x\mean{a_x}}{\sax{x}}\frac{1+(-1)^x\veps}{2}\right]^2+2\left[\sum_x\kappa_x D_{x,y}\frac{1+(-1)^x\veps}{2}\right]^2
\label{eq:LHS23_D}.
\end{align}
Now, when we calculate the full expression for the second summand in \cref{eq:afterlimchi}, e.g., take the sum over $y$, we notice that the first term in \cref{eq:LHS23_D} cancels out, because it does not depend on $y$.
Therefore, we intermediately conclude that 
\begin{equation}
    \frac{1}{2}\sum_{x_0,b,y} (-1)^y\frac{\left(\sum_{x_1} \chi_{x_0,x_1,y}^b \Pr(x_1|x_0)\right)^2}{\Pr(b|y)} = \sum_{y}(-1)^y\left[\sum_x\kappa_x D_{x,y}\frac{1+(-1)^x\veps}{2}\right]^2.
\end{equation}
Finally, the last term on the left-hand side of \cref{eq:afterlimchi} becomes
\begin{align}
    \sum_{x_0,x_1} \Pr(x_0,x_1)\sum_b \frac{(\chi_{x_0,x_1,1}^b)^2}{\Pr(b\vert y=1)} & = \sum_{x\in\Set{0,1}}\frac{1+(-1)^x\veps}{4}\frac{\kappa_x^2}{1-\mean{a_x}^2}\sum_{b}\frac{(\mean{a_x}+(-1)^b\mean{a_xb_1})^2}{1+(-1)^b\mean{b_1}}\\
    &=\sum_{x\in\Set{0,1}}\frac{1+(-1)^x\veps}{2}\kappa^2_x \left(D_{x,1}^2+\frac{\mean{a_x}^2}{1-\mean{a_x}^2}\right).\label{eq:LHS4_D}
\end{align}

Continuing with the terms on the right-hand side of \cref{eq:afterlimchi}, we again notice that the first term vanishes
\begin{equation}
    \sum_{x_0,x_1,a}(-1)^{a\oplus x_0}\frac{\kappa_{\xor}}{\sax{\xor}}\frac{1+(-1)^a\mean{a_{\xor}}}{2}\frac{1+(-1)^{\xor}}{4}=0,
\end{equation}
because of the summation over $x_0$.
The second summand on the right-hand side of \cref{eq:afterlimchi} simplifies to 
\begin{equation}
    \sum_{x_0,x_1,a}\frac{1+(-1)^a\mean{a_\xor}}{2}\frac{1+(-1)^\xor\veps}{4}\frac{\kappa_\xor^2}{1-\mean{a_\xor}^2}=\sum_{x\in\Set{0,1}}\frac{1+(-1)^x\veps}{2}\frac{\kappa_x^2}{1-\mean{a_x}^2}.\label{eq:RHS_D}
\end{equation}

Having expressed all the parts of the expression in \cref{eq:afterlimchi} in terms of $\kappa_{0},\kappa_1$, $\veps$ and the observed correlators, we bring the final expressions in \cref{eq:LHS23_D,eq:LHS4_D,eq:RHS_D} and group the terms with respect to $\kappa_0$ and $\kappa_1$
\begin{align}\label{eq:k0k1_D_condition}
\begin{split}
    \kappa_0^2\left(D_{0,0}^2\left(\frac{1+\veps}{2}\right)^2+D_{0,1}^2\frac{1-\veps^2}{4}-\frac{1+\veps}{2}\right) &+\kappa_1^2\left(D_{1,0}^2\left(\frac{1-\veps}{2}\right)^2+D_{1,1}^2\frac{1-\veps^2}{4}-\frac{1-\veps}{2}\right) \\
    &+2\kappa_0\kappa_1\frac{1-\veps^2}{4}\left(D_{0,0}D_{1,0}-D_{0,1}D_{1,1}\right)\leq 0.
    \end{split}
\end{align}
Now, we notice that the condition in \cref{eq:k0k1_D_condition} for arbitrary $k_0,k_1\in \RR$ is equivalent to a requirement that the following matrix is positive semidefinite
\begin{align}\everymath{\displaystyle}\label{eq:PSD}
    \begin{pmatrix}
        \frac{1+\veps}{1-\veps}(1-D_{0,0}^2)+1-D_{0,1}^2 & D_{0,1}D_{1,1}-D_{0,0}D_{1,0} \\
        D_{0,1}D_{1,1}-D_{0,0}D_{1,0} & \frac{1-\veps}{1+\veps}(1-D_{1,0}^2)+1-D_{1,1}^2
    \end{pmatrix}\geq 0,
\end{align}
where we have further simplified the terms in front of $\kappa_0^2$ and $\kappa_1^2$.
The diagonal terms of~\cref{eq:PSD} are both non-negative.
Therefore, \cref{eq:PSD} is equivalent to the determinant positivity condition,
\begin{equation}
    \left(D_{0,0}D_{1,0}-D_{0,1}D_{1,1}\right)^2\leq \left(\frac{1+\veps}{1-\veps}(1-D_{0,0}^2)+1-D_{0,1}^2\right)\left(\frac{1-\veps}{1+\veps}(1-D_{1,0}^2)+1-D_{1,1}^2\right).
\end{equation}
The final step is to choose the parameter $\veps$, such that 
\begin{equation}
    \frac{1+\veps}{1-\veps} = \sqrt{\frac{(1-D_{0,1}^2)(1-D_{1,0}^2)}{(1-D_{0,0}^2)(1-D_{1,1}^2)}},
\end{equation}
which leads to the TLM inequality (in the form given in Ref.~\cite{landau1988empirical})
\begin{equation}
    \abs{D_{0,0}D_{1,0}-D_{0,1}D_{1,1}}\leq \sqrt{1-D_{0,0}^2}\sqrt{1-D_{0,1}^2}+\sqrt{1-D_{1,0}^2}\sqrt{1-D_{1,1}^2}.
\end{equation}

